/** Convert one NAPI Change into the public bridge shape. */
export function fromNapiChange(value: Napi.Change): Change {
    return {
        path: value.path,
        uri: value.uri,
        isRemoved: value.isRemoved,
        moduleId: value.moduleId == null ? undefined : fromNapiModuleId(value.moduleId),
    };
}

/** Convert one Source into the NAPI transport shape. */
export function toNapiSource(value: Source): Napi.Source {
    if (value.kind === "fileSystem") {
        return {
            kind: "fileSystem",
            path: value.path,
        };
    }

    if (value.kind === "memory") {
        return {
            kind: "memory",
            root: value.root,
            edits: value.edits.map((item) => toNapiEdit(item)),
        };
    }

    throw new Error("unknown Source");
}

/** Convert one TextRange into the NAPI transport shape. */
export function toNapiTextRange(value: TextRange): Napi.TextRange {
    return {
        start: value.start,
        end: value.end,
    };
}

/** Convert one TextEdit into the NAPI transport shape. */
export function toNapiTextEdit(value: TextEdit): Napi.TextEdit {
    return {
        range: toNapiTextRange(value.range),
        text: value.text,
    };
}

/** Convert one Edit into the NAPI transport shape. */
export function toNapiEdit(value: Edit): Napi.Edit {
    if (value.kind === "setText") {
        return {
            kind: "setText",
            path: value.path,
            text: value.text,
        };
    }

    if (value.kind === "editText") {
        return {
            kind: "editText",
            path: value.path,
            edits: value.edits.map((item) => toNapiTextEdit(item)),
        };
    }

    if (value.kind === "setBytes") {
        return {
            kind: "setBytes",
            path: value.path,
            bytes: Array.from(value.bytes),
        };
    }

    if (value.kind === "remove") {
        return {
            kind: "remove",
            path: value.path,
        };
    }

    if (value.kind === "move") {
        return {
            kind: "move",
            from: value.from,
            to: value.to,
        };
    }

    throw new Error("unknown Edit");
}

/** Convert one NAPI Commit into the public bridge shape. */
export function fromNapiCommit(value: Napi.Commit): Commit {
    return {
        before: fromNapiRevision(value.before),
        after: fromNapiRevision(value.after),
        changes: value.changes.map((item) => fromNapiChange(item)),
    };
}

